# Try to find repetition
def find_repetition(grid):
    rows, cols = len(grid[0]), len(grid)
    for period in range(1, min(rows//2, cols//2) + 1):
        is_period = True
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != grid[r%period][c%period]:
                    is_period = False
                    break
            if not is_period:
                break
        if is_period:
            return True, period
    return False, -1

# Check for horizontal repetition
for r in range(2):
    pattern = find_repetition([test_input[r]])
    print(f"Row {r} has period {pattern[1]}")

